mapper.select:
SELECT m.material_code AS materialCode, m.material_name AS materialName, mg.group_name AS categoryName, m.unit AS unit, COALESCE(mol.min_qty, 0) AS minQty, COALESCE(mol.max_qty, 0) AS maxQty FROM material m LEFT JOIN material_group mg ON m.material_group_id = mg.material_group_id LEFT JOIN material_order_limit mol ON mol.material_code = m.material_code
AND mg.group_name = #{categoryName}
AND m.material_name = #{itemName}
ORDER BY mg.group_name, m.material_name

mapper.update:
UPDATE material_order_limit
SET min_qty = #{minQty}, max_qty = #{maxQty}
WHERE material_code = #{materialCode}
